INK=colors.HexColor('#1D2933'); MUTED=colors.HexColor('#586674'); TEAL=colors.HexColor('#087E8B'); PALE=colors.HexColor('#EFF6F6'); LINE=colors.HexColor('#D7DEDF'); RED=colors.HexColor('#9E3434')

cases = [
('01 | Current symptom with precise onset', 'I am 34 years old. Since yesterday evening, around 7 pm, I have had a fever and chills; the fever is still present this morning. A dry cough started about three days ago and is still bothering me. I have no chest pain and no difficulty breathing. I took paracetamol last night, which lowered the fever for a few hours, but it returned.', 'Age 34; fever current, onset yesterday 7 pm, temporary response then returned; dry cough current, onset 3 days ago; denies chest pain and breathing difficulty. Keep each symptom and time course distinct.'),
('02 | Sudden severe pain', 'I am 51. About 45 minutes ago I suddenly developed severe pain in the center of my chest while sitting at home. It has not gone away and feels worse when I walk. I am also short of breath now, which is new for me. I have not had this pain before, and I did not injure myself.', 'Chest pain current, sudden onset 45 minutes ago, severe/persistent/worse with walking; breathing difficulty current and new; no prior episode or injury. Check high-priority flags and both symptoms.'),
('03 | Blood in vomit, one episode', 'I am 29 years old. I vomited once this morning and noticed a small amount of bright red blood mixed in. The vomiting has stopped, but I still feel nauseated. I have no blood in my stool and no severe abdominal pain. I have never seen blood in vomit before.', 'Blood in vomit: happened today, one episode, not ongoing; nausea current; explicitly denies blood in stool and severe abdominal pain. Preserve event count and avoid turning denied symptoms into positives.'),
('04 | Blood in stool versus food coloring', 'I am 40. Today I noticed red streaks on the toilet paper after a bowel movement, but the stool itself was brown. I ate beetroot last night. I have no dizziness, weakness, black stool, or vomiting. This has happened once before several months ago, but it is not happening continuously.', 'Possible blood in stool is uncertain/contextual: red streak on paper once today, beetroot confounder, previous episode months ago. Capture uncertainty and negatives; do not present repeated/current bleeding as established.'),
('05 | Fainting with recovery', 'I am 67. At about 10 am I stood up from a chair, felt lightheaded, and briefly passed out for what my daughter says was less than a minute. I woke up quickly and know where I am now. I did not hit my head, and I have no chest pain or trouble breathing. I still feel a little dizzy when I stand.', 'Brief loss of consciousness today after standing; recovered/oriented; current mild postural dizziness. No head impact, chest pain, or breathing difficulty. Distinguish fainting from ongoing unconsciousness.'),
('06 | New weakness on one side', 'I am 72. At 8:15 this morning my right hand suddenly became weak and I started dropping my cup. My daughter also noticed that the right side of my mouth looked lower for about ten minutes. The face looks normal now, but my hand still feels weaker than usual. I have never had these symptoms before.', 'Sudden focal weakness onset 8:15 today, persistent right-hand weakness; facial asymmetry lasted ~10 minutes and resolved; first occurrence. Retain laterality and resolution instead of marking all symptoms current.'),
('07 | Headache with onset and absent warning signs', 'I am 23. A mild headache began gradually after lunch and has lasted about four hours. It is similar to headaches I sometimes get after skipping meals. I have no fever, neck stiffness, weakness, vision loss, vomiting, or recent head injury. Drinking water has helped a little.', 'Mild gradual headache current for ~4 hours; prior similar episodes after skipped meals; partially improved with water. Explicit negatives should remain absent; no red-flag additions.'),
('08 | Severe abdominal pain now improving', 'I am 46. At 2 pm I developed sudden severe pain in the lower right side of my abdomen. It was an 8 out of 10 for about an hour and is now a 4, but it has not gone away. I vomited once after the pain began. I do not have diarrhea or blood in my stool, and I have not had an operation recently.', 'Right lower abdominal pain current, sudden onset 2 pm, severity improving 8/10 to 4/10 but persistent; one vomiting episode after onset; denies diarrhea/blood in stool/recent operation.'),
('09 | Diarrhea resolved, fever persists', 'I am 31. I had watery diarrhea four times yesterday between noon and midnight, but none since I woke up today. I still have a fever of about 38.5 C this afternoon and feel tired. There was no blood in the diarrhea, and I have not vomited. My roommate had a similar stomach illness last week.', 'Diarrhea was yesterday, four episodes, resolved today; fever current this afternoon; fatigue current; denies blood/vomiting; possible exposure context. Avoid marking resolved diarrhea as current.'),
('10 | Breathing difficulty only during exertion', 'I am 58. For about two weeks I have become short of breath when climbing the two flights of stairs to my apartment. I breathe normally while sitting and can speak in full sentences. It has gradually become more noticeable over those two weeks. I have no sudden breathlessness, chest pain, fever, or cough.', 'Breathlessness current only with exertion, gradual onset 2 weeks, absent at rest; denies acute onset, chest pain, fever, cough. Preserve trigger and baseline status.'),
('11 | Cough history and current cough', 'I am 26. I had a cough for about ten days last month, and it completely stopped three weeks ago. A new dry cough started two days ago after a cold began; I have a runny nose now but no fever or shortness of breath. This cough is mild and happens mostly at night.', 'Old cough resolved three weeks ago; separate new mild dry cough current for 2 days with current runny nose; denies fever/breathing difficulty. Separate episodes rather than merging duration.'),
('12 | Medication reaction timeline', 'I am 38. I took my first dose of an antibiotic at 9 am. About 30 minutes later, itchy raised patches appeared on my arms and chest. The rash is still present, but my lips and tongue are not swollen and I am breathing normally. I have not taken another dose since the rash appeared.', 'Rash/hives current, onset ~30 minutes after first dose; medication exposure and sequence; denies lip/tongue swelling and breathing difficulty; no repeat dose.'),
('13 | Past allergy, no current reaction', 'I am 20. When I was a child, peanuts caused hives, so my family was told I might be allergic. I accidentally ate a peanut-free snack today and have no rash, swelling, vomiting, or breathing problem. I am asking whether the old allergy note should stay in my record. I have no symptoms right now.', 'Historical suspected peanut allergy from childhood; no present exposure or symptoms. Do not treat the history as an active allergic reaction.'),
('14 | Pregnancy status and symptom onset', 'I am 30 and 24 weeks pregnant. Since early this morning I have had a new, steady headache and blurred vision that has not improved after resting. I have no bleeding, fluid leakage, or abdominal pain. I do not know my blood pressure today. These symptoms were not present at my appointment last week.', 'Pregnancy context 24 weeks; current new steady headache and blurred vision since early morning; denies bleeding, fluid leakage, abdominal pain; blood pressure unknown.'),
('15 | Child with fever and hydration details', 'My son is 4 years old. His fever began last night and was 39 C when checked at 6 am; it is 38 C now after medicine. He has taken a few sips of water and urinated once since waking. He is awake and answers us, but is less playful than usual. He has no rash, stiff neck, or breathing difficulty.', 'Child age 4; fever current with measurements/times and medicine response; low intake/urination since waking; awake but less active; negatives explicit. Do not infer dehydration as confirmed unless supported.'),
('16 | Older adult confusion with baseline', 'My father is 81 and usually knows the date and recognizes everyone. Since yesterday afternoon he has been newly confused, asked the same question repeatedly, and could not find his bedroom. He is still confused this morning. He has no known dementia diagnosis, no fall, and no fever that we have measured.', 'Age 81; new confusion since yesterday afternoon, persistent/current, distinct from usual baseline; no known dementia, fall, measured fever. Retain baseline comparison and onset.'),
('17 | Seizure-like event, current recovery', 'I am 19. My brother saw my arms and legs jerk for about one minute at 3 pm today, and I did not respond during that time. I was sleepy and confused for around 20 minutes afterward, but I am awake and speaking normally now. I have never had an event like this before and did not hit my head.', 'Possible seizure-like episode at 3 pm lasting ~1 min with unresponsiveness; post-event confusion/sleepiness ~20 min, now resolved; first event, no head impact. Preserve sequence and current recovery.'),
('18 | Vomiting with no blood, improving', 'I am 44. I vomited three times between midnight and 4 am after eating at a restaurant. The last episode was six hours ago, and I have kept water down since then. There was no blood or coffee-ground material. I have mild stomach cramps but no severe pain or fever.', 'Vomiting three episodes overnight, resolved for 6 hours and tolerating water; explicitly no blood/coffee-ground; mild cramps current; no severe pain/fever.'),
('19 | Current blood in urine', 'I am 63. I noticed red urine on two trips to the bathroom this morning, beginning around 7 am. I have not seen clots, and I can urinate, but it stings. I have no flank pain, fever, or recent injury. My urine looked normal yesterday.', 'Visible blood in urine current today, two episodes since 7 am; painful urination; no clots, retention, flank pain, fever, injury; normal yesterday.'),
('20 | Menstrual bleeding, ordinary pattern', 'I am 27. My period started yesterday, on the date I expected, and the bleeding is about the same as usual for me. I change a pad every four to five hours. I have mild cramps that improve with a warm pack. I do not feel faint and have no severe abdominal pain.', 'Expected menstrual bleeding since yesterday, usual quantity/pattern; mild cramps responsive to warmth; denies faintness and severe pain. Do not misclassify as unexplained acute bleeding.'),
('21 | Chest discomfort after exercise, resolved', 'I am 35. After a long run yesterday, I felt a mild sore spot on my chest that hurt only when I pressed on it. It went away after a few hours and has not returned. I had no breathlessness, sweating, fainting, or pain spreading to my arm or jaw. I feel normal today.', 'Chest wall tenderness yesterday after running, resolved after hours; no recurrence/current symptoms; explicit associated negatives. Distinguish resolved tenderness from ongoing chest pain.'),
('22 | Chest pain radiating, active', 'I am 59. For the past 20 minutes I have had heavy pressure in my chest that began while I was carrying groceries. It spreads into my left arm and jaw and has not eased with rest. I feel sweaty and nauseated. I am not sure whether I am short of breath, but this pressure is still present.', 'Current heavy chest pressure, onset 20 minutes ago with exertion, radiates left arm/jaw, persistent despite rest; sweating/nausea current; breathing status uncertain. Keep uncertain separate from positive/negative.'),
('23 | Chronic symptom, no acute change', 'I am 48. My lower back has ached on and off for about six months, mostly after sitting at my desk all day. It is the same today as it has been for the last few weeks, not suddenly worse. I have no leg weakness, numbness around the groin, loss of bladder control, fever, or recent injury.', 'Intermittent chronic back pain ~6 months, unchanged/no acute worsening; trigger sitting; listed emergency-associated negatives. Preserve chronicity and stable status.'),
('24 | New numbness with exact laterality', 'I am 42. Since 11 am today, the fingers on my left hand have felt numb and tingly. It began while I was typing and has continued for three hours. My right hand feels normal, and I can grip objects normally. I have no face droop, speech trouble, or weakness.', 'Left-finger numbness/tingling current since 11 am for 3 hours; right side normal; grip preserved; denies face/speech/weakness. Preserve laterality.'),
('25 | Head injury and delayed vomiting', 'I am 16. I hit the back of my head on a low shelf at 5 pm yesterday; I did not black out. I had a headache afterward, and I vomited once at 8 pm. The headache is mild now and the vomiting has not happened again. I am alert, with no confusion, weakness, or vision change.', 'Head impact yesterday 5 pm without loss of consciousness; headache began after, now mild; single vomiting episode 3 hours later, no recurrence; alert/no confusion or focal signs.'),
('26 | Symptoms explicitly denied after exposure', 'I am 33. My coworker tested positive for flu, and I sat beside them yesterday for an hour. I do not have fever, cough, sore throat, runny nose, aches, or breathing problems today. I am worried because I have asthma, but my breathing is at its usual baseline and I have not needed my rescue inhaler.', 'Exposure yesterday; symptom list explicitly absent; asthma is background and breathing baseline unchanged, no rescue inhaler needed. Do not convert concern/exposure into current infection symptoms.'),
('27 | Mixed Hindi-English current symptoms', 'मेरी उम्र 52 साल है। कल रात 9 बजे से बुखार है और अभी भी है। आज सुबह से सांस फूल रही है, खासकर चलने पर, लेकिन बैठने पर ठीक लगता है। खांसी पिछले चार दिन से है। सीने में दर्द नहीं है और बेहोशी भी नहीं हुई।', 'Age 52; fever current since 9 pm last night; breathlessness current with exertion since this morning and relieved at rest; cough 4 days; denies chest pain/fainting. Check language-aware symptom and onset extraction.'),
('28 | Hinglish resolved symptom and current complaint', 'Main 28 saal ka hoon. Kal raat spicy khana khane ke baad do baar vomiting hui, lekin subah se bilkul nahi hui aur paani ruk raha hai. Aaj dopahar se pet mein halka dard hai, par severe nahi. Fever nahi hai, stool mein blood nahi hai, aur chakkar bhi nahi aa rahe.', 'Age 28; vomiting twice last night after food, resolved this morning, water tolerated; mild non-severe abdominal pain current since afternoon; denies fever, blood in stool, dizziness.'),
('29 | Urdu/Hindi pain history versus current status', 'میری عمر 36 سال ہے۔ پچھلے مہینے دو دن پیٹ میں درد تھا، لیکن اب درد بالکل نہیں ہے۔ آج صرف ہلکی متلی ہے جو کھانے کے بعد شروع ہوئی۔ بخار، الٹی، یا پاخانے میں خون نہیں ہے۔', 'Age 36; abdominal pain occurred last month for 2 days and is resolved; mild nausea current after food; denies fever/vomiting/blood in stool. Verify not translated into false active pain.'),
('30 | Multiple symptoms with different onsets', 'I am 54. A runny nose began five days ago and is improving. A sore throat started three days ago and is still present. Fever began only this morning and measured 38.2 C at 9 am. I have no cough or breathing difficulty. I took a home COVID test yesterday, before the fever started, and it was negative.', 'Runny nose 5 days, improving/current; sore throat 3 days, current; fever new today at 9 am, current; denies cough/breathing difficulty; negative test predates fever. Separate onset for every symptom.'),
('31 | Symptom after medication stopped', 'I am 47. I began a new blood pressure medicine two weeks ago. A dry cough started about four days after I began it and continued daily. My doctor told me to stop it two days ago; the cough is still present but seems less frequent. I have no fever, mucus, or shortness of breath.', 'New medicine started 2 weeks ago; dry cough onset ~4 days after, ongoing but improving after medication stopped 2 days ago; denies fever/mucus/breathlessness. Preserve exposure timing and trend without asserting causation.'),
('32 | Possible overdose with no symptoms yet', 'I am 22. At around 1 pm I accidentally took two doses of my usual tablets within an hour, instead of one dose. I feel normal right now and have no nausea, dizziness, sleepiness, or breathing problem. I do not know whether this amount is dangerous. The package is with me.', 'Possible medication dosing error at 1 pm; currently asymptomatic with explicit negatives; unknown toxicity. Keep exposure separate from symptoms and do not invent overdose effects.'),
('33 | Fever in context of recent surgery', 'I am 61 and had abdominal surgery four days ago. My temperature was normal yesterday, but today at noon it reached 38.3 C and is still 38.1 C now. The incision is more red than yesterday and has a small amount of yellow drainage. I have increasing soreness around it but no vomiting or breathing difficulty.', 'Postoperative context, surgery 4 days ago; fever new today and current with measurements; incision redness/drainage worsening; increasing local pain; denies vomiting/breathlessness. Preserve change from yesterday.'),
('34 | Wound bleeding that stopped', 'I am 18. I cut my finger while cooking at 6 pm. It bled for about ten minutes, then stopped after I held a clean cloth on it. There is no bleeding now. The cut is small, and I can bend and feel the finger normally. I did not faint or feel dizzy.', 'Finger cut at 6 pm; bleeding lasted ~10 min and resolved; no current bleeding; movement/sensation normal; denies faintness/dizziness. Do not retain bleeding as current.'),
('35 | Dehydration-like details without conclusion', 'I am 39. I have had loose stools about six times since yesterday morning and vomited twice overnight. Since midnight I have only urinated once, and my mouth feels dry when I wake up. I can keep small sips down now. I have no blood in stool or vomit and no fainting.', 'Diarrhea six times since yesterday morning and vomiting twice overnight; reduced urination since midnight and dry mouth; now tolerating sips; denies blood/fainting. Extract findings without asserting a diagnosis.'),
('36 | Dizziness with positional pattern', 'I am 70. For three days I have had brief spinning for about ten seconds whenever I roll onto my right side in bed. It stops if I keep still, and I feel normal between episodes. I have not fainted, and I have no weakness, speech change, chest pain, or new hearing loss.', 'Brief positional vertigo episodes for 3 days, ~10 sec each, triggered by rolling right; resolves at rest, normal between episodes; denies listed symptoms. Distinguish episodic from continuous dizziness.'),
('37 | Chronic breathlessness plus acute worsening', 'I am 66 and have been mildly short of breath on hills for about a year. Since this morning I am also breathless while sitting, which is new and worse than my usual pattern. I have a cough with yellow mucus for three days and a fever since last night. I have no chest pain or leg swelling.', 'Baseline exertional breathlessness for a year; acute new dyspnea at rest since morning; productive cough 3 days; fever since last night; denies chest pain/leg swelling. Do not collapse baseline and acute change.'),
('38 | Pain resolved before encounter, concern remains', 'I am 30. I had a sharp pain on the right side of my abdomen for about 20 minutes yesterday afternoon, then it completely stopped. It has not returned today. I am eating normally and have no nausea, fever, diarrhea, or tenderness now. I am contacting you because I am worried it might happen again.', 'Right abdominal pain yesterday, 20 minutes, resolved with no recurrence today; currently asymptomatic for related symptoms; concern is not itself a symptom.'),
('39 | Ambiguous “not anymore” reference', 'I am 45. I had a fever on Monday and Tuesday, but not anymore; my temperature has been normal since Wednesday morning. The cough is different: it began Monday and is still present today. I had body aches until yesterday, and those have also stopped. I have no breathing difficulty.', 'Fever resolved Wednesday morning; cough current since Monday; body aches resolved yesterday; denies breathing difficulty. Resolve pronouns/status correctly for each symptom.'),
('40 | Uncertain timing and uncertain symptom', 'I am 57. I may have felt my heart beat irregularly sometime last night, but I was half asleep and am not certain. I have not noticed it today. I do have mild tiredness today, which may be because I slept poorly. I have no chest pain, fainting, or shortness of breath.', 'Possible/uncertain palpitations last night, not noticed today; mild fatigue current with uncertain cause/poor sleep; denies chest pain, fainting, breathlessness. Preserve uncertainty rather than upgrading to definite active event.'),
('41 | Two people in one pasted narrative', 'I am 32 and have had a sore throat since yesterday, but no fever or cough. My child, age 6, is the one with a fever: it began this morning and is 38.4 C now. The child is drinking and playing, with no rash or breathing difficulty. Please do not mix our symptoms together.', 'Two subjects: adult age 32 has current sore throat since yesterday, denies fever/cough; child age 6 has fever onset this morning, current 38.4 C, drinking/playing, denies rash/breathlessness. Check subject attribution.'),
('42 | Correction within the same statement', 'I am 50. I first said the pain started this morning, but I checked my messages and it actually began yesterday at about 6 pm. It is a mild headache and is still present now. I have not had vomiting or vision changes. I have no fever.', 'Use corrected onset yesterday ~6 pm, not initial mistaken “this morning”; mild headache current; denies vomiting, vision changes, fever. Test whether self-correction is respected.'),
('43 | “No longer” and recurrence', 'I am 41. I had a fever yesterday that went away overnight. It came back today at 2 pm and is 38.1 C now. The cough has continued without stopping since Saturday. I had chills only during last night and do not have chills now.', 'Fever first episode yesterday resolved overnight, recurred today 2 pm and is current; cough continuous since Saturday; chills last night resolved. Represent recurrence and status per symptom.'),
('44 | No onset known, symptom current', 'I am 75. My ankles are swollen today, and the swelling is still visible now. I do not know exactly when it began because I noticed it only this morning. It is on both sides and does not hurt. I have no sudden breathlessness or chest pain.', 'Bilateral ankle swelling current, noticed this morning but true onset unknown; painless; denies acute breathlessness/chest pain. Keep observed time distinct from onset.'),
('45 | Symptom after food, recurrence count', 'I am 24. Each time I drank milk today, I got crampy abdominal pain within about an hour; this happened twice, at breakfast and lunch. The pain faded within 30 minutes both times and is gone now. I have no diarrhea, rash, swelling, or breathing problem. I have not had this pattern with milk before.', 'Two reproducible episodes of cramps after milk, onset within ~1 hour, each resolved in 30 minutes, absent now; denies diarrhea/rash/swelling/breathing issue; new pattern. Capture trigger, count, latency, and resolution.'),
('46 | Infection symptoms with measurement and medication', 'I am 37. A fever began around 4 am today; my thermometer read 39.1 C at 8 am before medicine and 37.8 C at noon afterward. I still feel warm and achy, but the chills stopped after the medicine. I have a dry cough since yesterday. I have no chest pain or confusion.', 'Fever current/improved after medicine, onset ~4 am with measurements; aches current; chills resolved after medicine; dry cough since yesterday; denies chest pain/confusion. Avoid treating temperature reduction as full resolution.'),
('47 | English symptoms with Hindi quote and negation', 'I am 43. My mother said, “सांस नहीं फूल रही” - she means I am NOT short of breath. I do have a cough that started two days ago and a mild fever since last night. I can walk across the room normally. No chest pain, no blue lips, and no fainting.', 'Cough current 2 days; mild fever current since last night; breathlessness explicitly negated in Hindi and English; normal walking; denies chest pain, cyanosis, fainting. Test multilingual negation handling.'),
('48 | Follow-up with changed status', 'I am 56. At yesterday’s visit I had vomiting and severe stomach pain. I have not vomited since 9 pm yesterday, and the severe pain has settled to a mild ache today. I can drink fluids and ate toast this morning. I have no fever or blood in vomit or stool.', 'Follow-up timing: vomiting resolved since 9 pm yesterday; severe pain improved but mild ache current today; oral intake resumed; denies fever and blood. Preserve improvement, not unchanged severity.'),
]

styles = {
 'title': ParagraphStyle('title', fontName='Helvetica-Bold', fontSize=21, leading=25, textColor=INK, spaceAfter=5),
 'subtitle': ParagraphStyle('subtitle', fontName='Helvetica', fontSize=10, leading=14, textColor=MUTED, spaceAfter=12),
 'body': ParagraphStyle('body', fontName='FreeSans', fontSize=10.4, leading=14.2, textColor=INK),
 'verify': ParagraphStyle('verify', fontName='FreeSans', fontSize=9.1, leading=12.2, textColor=MUTED, leftIndent=10, borderColor=LINE, borderWidth=0, spaceBefore=5),
 'intro': ParagraphStyle('intro', fontName='Helvetica', fontSize=9.3, leading=13, textColor=INK),
 'section': ParagraphStyle('section', fontName='Helvetica-Bold', fontSize=10.5, leading=13, textColor=TEAL, spaceBefore=8, spaceAfter=3),
}

def page(canvas, doc):
    canvas.saveState()
    w,h=A4
    canvas.setFillColor(INK); canvas.rect(0,h-7,w,7,fill=1,stroke=0)
    canvas.setStrokeColor(LINE); canvas.line(42,31,w-42,31)
    canvas.setFont('Helvetica',7.5); canvas.setFillColor(MUTED)
    canvas.drawString(42,19,'CareFlow AI | Synthetic manual model checks | Not clinical guidance')
    canvas.drawRightString(w-42,19,f'{doc.page}')
    canvas.restoreState()

story=[Spacer(1,8), Paragraph('Detailed Manual Model Test Cases',styles['title']), Paragraph('48 synthetic scenarios for checking symptom extraction, timing, status, negation, uncertainty, and subject attribution',styles['subtitle']), Paragraph('How to use',styles['section']), Paragraph('Create a fresh synthetic case in the app for each numbered item. Copy only the case paragraph into the appropriate input field. Then compare the app output with the “Check” line. Record exact mismatches and any extra flags separately. These cases are designed to probe extraction and safety-rule behavior; they are not diagnoses or medical advice.',styles['intro']), Paragraph('How to judge the result',styles['section']), Paragraph('Check that the model names the right symptom, person, body side, onset, duration, episode count, severity, trigger, and whether it is current, resolved, recurring, denied, or uncertain. For rule flags, compare with your app’s configured rules; flag labels can depend on that configuration. An unexpected model flag is useful to record, even when no rule flag is expected. Do not enter real patient data.',styles['intro']), Spacer(1,7), Paragraph('CASE INPUTS',styles['section'])]

for i,(title, paragraph, verify) in enumerate(cases,1):
    block=[Spacer(1,9), Paragraph(f'<b>{escape(title)}</b>', ParagraphStyle(f'h{i}',fontName='Helvetica-Bold',fontSize=10.2,leading=13,textColor=INK,spaceAfter=4)), Paragraph(escape(paragraph),styles['body']), Paragraph(f'<b>Check:</b> {escape(verify)}',styles['verify']), Paragraph('Result:  [ ] matches  [ ] missing detail/flag  [ ] extra detail/flag     Notes: __________________________________',ParagraphStyle(f'log{i}',fontName='Helvetica',fontSize=7.7,leading=10,textColor=TEAL,spaceBefore=5))]
    story.append(KeepTogether(block))

OUT.parent.mkdir(parents=True,exist_ok=True)
doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=30,bottomMargin=43,title='CareFlow AI Detailed Manual Model Test Cases',author='CareFlow AI project team',subject='Synthetic model behavior checks; not clinical advice')
doc.build(story,onFirstPage=page,onLaterPages=page)
print(f'Created {OUT} with {len(cases)} detailed cases')
